-- Real content inventory only; not proof of human review or browser acceptance.
SELECT c.id AS course_id,c.title,c.is_published,c.practice_course_scope,t.id AS topic_id,t.topic_code,t.title AS topic_title,coalesce(l.is_published,false) AS lesson_published,(SELECT count(*) FROM public.course_topic_videos m WHERE m.course_id=c.id AND m.topic_id=t.id) AS video_count,l.game_path IS NOT NULL AS has_game,(SELECT count(*) FROM public.questions q JOIN public.question_versions v ON v.id=q.current_version_id AND v.question_id=q.id WHERE v.primary_topic_id=t.id AND q.status='approved' AND v.status='approved' AND v.question_type='mcq_single' AND (c.practice_course_scope='BC' OR v.course_scope IN ('AB','BOTH'))) AS applicable_question_count
FROM public.courses c JOIN public.course_curriculum_units m ON m.course_id=c.id JOIN public.curriculum_units u ON u.id=m.unit_id JOIN public.curriculum_topics t ON t.unit_id=u.id LEFT JOIN public.course_topic_content l ON l.course_id=c.id AND l.topic_id=t.id
WHERE c.id='fccc7540-0c29-43be-8682-ae90ff2534cb' AND u.unit_number=1 ORDER BY t.order_index;
